import{z as i,x as l,o as t,c as d,q as s,j as B,D as a,d as A,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"RSA 攻击面","description":"","frontmatter":{"title":"RSA 攻击面","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rsa-attacks.md","filePath":"cs/rsa-attacks.md","lastUpdated":1791063341000}'),p={name:"cs/rsa-attacks.md"};function h(c,E,D,m,F,P){const r=l("Mermaid");return t(),d("div",null,[E[2]||(E[2]=s('<h1 id="rsa-攻击面" tabindex="-1">RSA 攻击面 <a class="header-anchor" href="#rsa-攻击面" aria-label="Permalink to &quot;RSA 攻击面&quot;">​</a></h1><div class="epigraph"><p>RSA 的数学对象很稳，工程对象很脆：填充实现、密钥复用、小指数广播、侧信道比「分解模数」更常把系统打穿。</p><footer>—— Boneh, Twenty Years of Attacks on the RSA Cryptosystem, Notices of the AMS, 1999；对照 Anderson 对实现失败</footer></div><p>上一课<a href="/cs/rsa-oaep">OAEP</a>给出正确填充。缺口是<strong>错误清单</strong>：哪些合同一破，归约作废。本课只列机制与防御，不提供利用步骤或参数求解程序。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OAEP 在实现里若回退到 PKCS#1 v1.5 加密，历史 Bleichenbacher 预言机就会回来——只陈述「可区分的填充错误」。共模多指数、低加密指数广播、公共私钥因子，都是密钥管理与参数选择失败。缺口是把这些收成「不要做」，而不是重讲分解算法。<span class="marginnote">术语翻译：「预言机」就是用「把系统当成只会答对/错的应答机、反复喂给它精心改造过的密文、从对错里榨出信息」的手段来做「不正面硬破、从侧面问出来」的事——服务器报不报「填充格式错误」，本身就是一条可被利用的判据。</span></p><h3 id="侧信道也算攻击面" tabindex="-1">侧信道也算攻击面 <a class="header-anchor" href="#侧信道也算攻击面" aria-label="Permalink to &quot;侧信道也算攻击面&quot;">​</a></h3><p>模幂若按比特走不同时间或不同缓存，密钥位可漏。<a href="/cs/side-channel">侧信道</a>已给模型，本课只把 RSA 实现标进同一模型。</p><p><span class="marginnote">Boneh 1999 综述是合法文献。课程禁止复现其中的构造步骤。防御：OAEP/PSS、恒定时间、一密钥一用途、足够大的随机填充、换 ECDH。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按来源分类：填充预言、代数关系（共模/广播）、弱素数生成、实现泄漏。每类对应一条工程规则。指向后课 ECDH：许多新协议直接离开 RSA 封装。<span class="marginnote">常见误区：初学者容易以为「模数够大就安全」——2048 位模数照样挡不住共模攻击：两个用户共用同一个 \\(n\\)、各自用小指数加密同一消息，不用分解模数就能恢复明文。模数大小只管「分解有多难」，管不了「密钥怎么用」。</span></p>',11)),(t(),B(o,null,{default:a(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RSA%5B%22RSA%20%E9%99%B7%E9%97%A8%22%5D%20--%3E%20PAD%5B%22%E5%A1%AB%E5%85%85%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20RSA%20--%3E%20KEY%5B%22%E5%AF%86%E9%92%A5%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%22%5D%0A%20%20RSA%20--%3E%20IMP%5B%22%E6%81%92%E5%AE%9A%E6%97%B6%E9%97%B4%E6%A8%A1%E5%B9%82%22%5D%0A%20%20PAD%20--%3E%20FAIL%5B%22%E5%8F%AF%E5%8C%BA%E5%88%86%E9%94%99%E8%AF%AF%E5%88%99%E5%90%88%E5%90%8C%E7%A0%B4%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[A("可证明安全只在游戏前提成立时成立。攻击面课的工作是列出前提：唯一用途、不可区分失败、随机填充、大模数、无泄漏实现。分解本身仍难，不等于产品安全。"),e("span",{class:"marginnote"},"直觉类比：可证明安全像保险合同——条款（前提）逐条成立才赔；实现里出现可区分错误、密钥复用、时序泄漏，任何一条违约，理赔（安全归约）就作废，数学本身不背锅。")],-1)),(t(),B(o,null,{default:a(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20GAME%5B%22%E5%AE%89%E5%85%A8%E5%BD%92%E7%BA%A6%E4%BE%9D%E8%B5%96%E7%9A%84%E5%89%8D%E6%8F%90%22%5D%20--%3E%20P1%5B%22%E5%AF%86%E9%92%A5%E4%B8%80%E5%AF%86%E9%92%A5%E4%B8%80%E7%94%A8%E9%80%94%22%5D%0A%20%20GAME%20--%3E%20P2%5B%22%E5%A1%AB%E5%85%85%E9%94%99%E8%AF%AF%E4%B8%8D%E5%8F%AF%E5%8C%BA%E5%88%86%22%5D%0A%20%20GAME%20--%3E%20P3%5B%22%E7%B4%A0%E6%95%B0%E7%8B%AC%E7%AB%8B%E4%B8%94%E9%9A%8F%E6%9C%BA%22%5D%0A%20%20GAME%20--%3E%20P4%5B%22%E5%AE%9E%E7%8E%B0%E6%81%92%E5%AE%9A%E6%97%B6%E9%97%B4%22%5D%0A%20%20P1%20--%20%22%E8%BF%9D%E7%BA%A6%22%20--%3E%20A1%5B%22%E5%85%B1%E6%A8%A1%2F%E5%B9%BF%E6%92%AD%EF%BC%9A%E6%98%8E%E6%96%87%E8%A2%AB%E4%BB%A3%E6%95%B0%E6%8E%A8%E5%87%BA%22%5D%0A%20%20P2%20--%20%22%E8%BF%9D%E7%BA%A6%22%20--%3E%20A2%5B%22%E5%A1%AB%E5%85%85%E9%A2%84%E8%A8%80%E6%9C%BA%EF%BC%9A%E5%AF%86%E6%96%87%E8%A2%AB%E9%80%90%E4%BD%8D%E9%97%AE%E5%87%BA%22%5D%0A%20%20P3%20--%20%22%E8%BF%9D%E7%BA%A6%22%20--%3E%20A3%5B%22%E5%BC%B1%E7%B4%A0%E6%95%B0%EF%BC%9A%E6%A8%A1%E6%95%B0%E8%A2%AB%E5%88%86%E8%A7%A3%22%5D%0A%20%20P4%20--%20%22%E8%BF%9D%E7%BA%A6%22%20--%3E%20A4%5B%22%E6%97%B6%E5%BA%8F%2F%E7%BC%93%E5%AD%98%E4%BE%A7%E4%BF%A1%E9%81%93%EF%BC%9A%E5%AF%86%E9%92%A5%E4%BD%8D%E5%A4%96%E6%BC%8F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写因数分解或 Coppersmith 方法的操作指导。下一课椭圆曲线 DH：换群，不换「封装会话键」这一层目标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OAEP 是正确形状；实现与密钥管理才是常见破口。</li><li>可区分填充错误、共模、弱随机，都让归约退出。</li><li>一密钥一用途；恒定时间。</li><li>后课 ECDH/X25519 换群做协商。</li><li>出处：Boneh, 1999；Bleichenbacher（作为历史失败模式点名）；Anderson, <em>Security Engineering</em>。</li></ul>',4))])}const u=i(p,[["render",h]]);export{S as __pageData,u as default};
